mapper.select:
SELECT oi.id, oi.order_id, oi.spu_id, oi.sku_id, oi.spu_code_snapshot, oi.product_name_snapshot, oi.sku_code_snapshot, oi.spec_name_snapshot, oi.spec_values_snapshot, oi.sale_unit_snapshot, oi.product_type_snapshot, oi.ordered_quantity, oi.actual_quantity, oi.actual_quantity_source, oi.actual_quantity_reason, oi.sort_order, oi.version, oi.created_at, oi.updated_at FROM sales_order_item oi JOIN sales_order o ON o.id = oi.order_id AND o.deleted = FALSE WHERE o.status = 'CONFIRMED' AND oi.deleted = FALSE AND oi.actual_quantity IS NOT NULL AND oi.actual_quantity > 0 AND o.confirmed_at >= #{startAt} AND o.confirmed_at < #{endAt}
AND FALSE
ORDER BY oi.sku_id ASC, o.confirmed_at ASC, oi.id ASC

SELECT d.id, d.sales_order_id, d.sales_order_no_snapshot, d.sales_order_item_id, d.sku_id, d.sku_code_snapshot AS sku_code, d.sku_name_snapshot AS sku_name, d.product_name_snapshot AS product_name, d.spec_values_snapshot AS spec_values, d.demand_unit_snapshot AS demand_unit, d.product_type_snapshot AS product_type, d.required_quantity, d.allocated_quantity, (d.required_quantity - d.allocated_quantity) AS unallocated_quantity, d.supplier_id, s.name AS supplier_name, d.warehouse_id, w.name AS warehouse_name, d.status, d.demand_date, d.source_confirmed_at, d.version, d.created_at FROM purchase_demand d LEFT JOIN supplier s ON s.id = d.supplier_id AND s.deleted = FALSE LEFT JOIN warehouse w ON w.id = d.warehouse_id AND w.deleted = FALSE WHERE d.deleted = FALSE
AND d.sales_order_no_snapshot ILIKE CONCAT('%', #{query.salesOrderNo}, '%')
AND d.sku_id = #{query.skuId}
AND d.supplier_id = #{query.supplierId}
AND d.warehouse_id = #{query.warehouseId}
AND d.status = #{query.status}
AND d.demand_date >= #{query.demandDateFrom}
AND d.demand_date < #{query.demandDateTo}
AND d.purchaser_id IN #{scopeId}
AND FALSE
ORDER BY d.demand_date DESC, d.id DESC

SELECT s.*, (s.reserved_quantity - s.selected_order_reserved_quantity) AS other_reserved_quantity, (s.available_quantity + s.selected_order_reserved_quantity) AS stock_available_for_selected_orders, CASE WHEN s.inventory_unit IS NOT NULL AND s.inventory_unit <> s.demand_unit THEN NULL ELSE GREATEST(s.order_demand_quantity - (s.available_quantity + s.selected_order_reserved_quantity), 0) END AS stock_comparison_gap, CASE WHEN s.inventory_unit IS NULL THEN 'NO_BALANCE' WHEN s.inventory_unit <> s.demand_unit THEN 'UNIT_MISMATCH' WHEN (s.available_quantity + s.selected_order_reserved_quantity) = 0 THEN 'ZERO_STOCK' WHEN s.order_demand_quantity > (s.available_quantity + s.selected_order_reserved_quantity) THEN 'SHORTAGE' ELSE 'STOCK_ENOUGH' END AS calculation_status FROM ( SELECT oi.sku_id, k.sku_code, p.name AS product_name, k.spec_name AS sku_name, cat.name AS category_name, oi.sale_unit_snapshot AS demand_unit, b.unit AS inventory_unit, COUNT(DISTINCT oi.order_id) AS source_order_count, COUNT(oi.id) AS source_line_count, SUM(oi.actual_quantity) AS order_demand_quantity, COALESCE(b.quantity, 0) AS on_hand_quantity, COALESCE(b.reserved_quantity, 0) AS reserved_quantity, (COALESCE(b.quantity, 0) - COALESCE(b.reserved_quantity, 0)) AS available_quantity, COALESCE((SELECT SUM(r.quantity) FROM inventory_reservation r WHERE r.deleted = FALSE AND r.status = 'ACTIVE' AND r.source_document_type = 'SALES_ORDER_ITEM' AND r.warehouse_id = #{query.warehouseId} AND r.sku_id = oi.sku_id /* 「本批」= 与外层同源的确认窗口内的订单集合 */ AND r.source_document_id IN (SELECT w.id FROM sales_order w WHERE w.deleted = FALSE AND w.status = 'CONFIRMED' AND w.confirmed_at >= #{query.startAt} AND w.confirmed_at < #{query.endAt})), 0) AS selected_order_reserved_quantity FROM sales_order_item oi JOIN sales_order o ON o.id = oi.order_id AND o.deleted = FALSE LEFT JOIN product_sku k ON k.id = oi.sku_id LEFT JOIN product_spu p ON p.id = k.spu_id LEFT JOIN product_category cat ON cat.id = p.category_id LEFT JOIN inventory_balance b ON b.sku_id = oi.sku_id AND b.warehouse_id = #{query.warehouseId} AND b.deleted = FALSE WHERE o.status = 'CONFIRMED' AND oi.deleted = FALSE AND oi.actual_quantity IS NOT NULL AND oi.actual_quantity > 0 AND o.confirmed_at >= #{query.startAt} AND o.confirmed_at < #{query.endAt}
AND p.category_id = #{query.categoryId}
AND (p.spu_code ILIKE CONCAT('%', #{query.keyword}, '%') OR p.name ILIKE CONCAT('%', #{query.keyword}, '%') OR k.sku_code ILIKE CONCAT('%', #{query.keyword}, '%'))
AND #{query.warehouseId} IN #{scopeId}
AND FALSE
GROUP BY oi.sku_id, oi.sale_unit_snapshot, b.unit, b.quantity, b.reserved_quantity, k.sku_code, k.spec_name, p.name, cat.name ) s ORDER BY stock_comparison_gap DESC NULLS LAST, s.sku_id ASC

mapper.update:
UPDATE purchase_demand
SET allocated_quantity = #{allocatedQuantity},
    status             = #{status},
    supplier_id        = #{supplierId},
    version            = version + 1,
    updated_at         = CURRENT_TIMESTAMP,
    updated_by         = #{operator}
WHERE id = #{id}
  AND version = #{version}
  AND deleted = FALSE

UPDATE purchase_demand
SET deleted    = TRUE,
    version    = version + 1,
    updated_at = CURRENT_TIMESTAMP,
    updated_by = #{operator}
WHERE id = #{id}
  AND version = #{version}
  AND deleted = FALSE
